 $('#configurations').innerHTML='<div id="configuration-actions" class="actions"></div>'+configs.slice(0,100).map((c,i)=>`<div class="config ${c.frozen?'frozen':''}"><label><input type="checkbox" data-config-select="${i}" aria-label="Select configuration ${i+1}"> Configuration ${i+1}${c.frozen?' · Frozen':''}</label>${configHTML(c)}<button data-trace-config="${i}">View trace</button></div>`).join('')+(configs.length>100?'<p>Showing first 100 configurations.</p>':'')+(!configs.length?'<p class="hint">No active configurations remain.</p>':'');
