function showTrace(c){message('Computation trace',c?`<div class="scroll">${[...(c.trace||[]),c].map((x,i)=>`<div class="config"><div class="small">Step ${i}</div>${configHTML(x)}</div>`).join('')}</div>`:'<p>No accepting trace was found.</p>');}
