function grammarPanel(){if(tab==='Multiple Parse'){grammarBatchPanel();return;}const m=model();if(tab==='Editor'){toolbar([['Add production',()=>{const t=$('#grammar-input');t.value+='\nA → ';t.focus();}],['Apply grammar',applyGrammar,'primary'],['Classify',()=>{applyGrammar();message('Grammar classification',`<p>${G.classify(m.productions)}</p>`);}]],'Uppercase letters are variables. Empty right sides are λ.');$('#content').innerHTML=`<div class="panel split"><div><label class="field"><span>Productions · one rule per line</span><textarea id="grammar-input" rows="13" spellcheck="false">${E(G.grammarText(m.productions))}</textarea></label><p class="hint">Use → or ->. Alternatives can be separated with |. The first production defines the start variable.</p></div><div class="card"><h3>A language, one production at a time</h3><p>S → aSb adds matching a and b symbols around S.<br>S → λ ends the derivation.</p><pre>S ⇒ aSb ⇒ aaSbb ⇒ aabb</pre><p>The Parse tab offers derivation search, LL(1), SLR and CYK. Transform removes empty, unit and useless productions before Chomsky normal form conversion.</p><div class="result">${E(G.classify(m.productions))}</div></div></div>`;$('#grammar-input').onchange=safe(applyGrammar);return;}
 if(tab==='Transform'){toolbar([['Remove λ productions',()=>transform(G.removeLambda)],['Remove unit productions',()=>transform(G.removeUnit)],['Remove useless productions',()=>transform(G.removeUseless)],['Chomsky normal form',()=>transform(G.cnf),'primary']]);$('#content').innerHTML=`<div class="panel split"><div><h3>Original grammar</h3><pre>${E(G.grammarText(m.productions))}</pre><p class="hint">Each operation opens its result as a new grammar. The original remains available. Empty-word membership is preserved by the web converter.</p></div><div class="card"><h3>The transformation pipeline</h3><ol class="hint"><li>Find nullable variables and add omission variants.</li><li>Replace unit chains with their non-unit productions.</li><li>Remove non-generating and unreachable variables.</li><li>Introduce terminal variables and split long right sides.</li></ol></div></div>`;return;}
 toolbar([['Show FIRST / FOLLOW',()=>showTable('first')],['Build LL(1) table',()=>showTable('ll')],['Build SLR table',()=>showTable('lr')]]);$('#content').innerHTML=`<div class="panel split"><div><label class="field"><span>Input string</span><input id="grammar-word" value="aabb"></label><label class="field"><span>Parsing algorithm</span><select id="parse-method"><option value="derive">Brute-force derivation</option><option value="llParse">LL(1)</option><option value="lrParse">SLR (JFLAP’s LR workflow)</option><option value="cyk">CYK (convert to CNF first)</option></select></label><div class="actions" id="parse-actions"></div><div id="parse-result"></div><p class="hint">Derivation search is bounded. An unfinished search is reported as a limit, not rejection. Parsing tables expose conflicts rather than silently choosing a rule.</p></div><div id="parse-output" class="scroll"></div></div>`;$('#parse-actions').append(button('Parse',()=>{const method=$('#parse-method').value,r=G[method](m.productions,A.empty($('#grammar-word').value));$('#parse-result').innerHTML=`<div class="result ${r.status}">${E(r.status.toUpperCase())}</div>`;if(method==='cyk')$('#parse-output').innerHTML='<h3>CYK chart</h3><table>'+r.cells.map((row,i)=>'<tr><th>Length '+(i+1)+'</th>'+row.slice(0,r.cells.length-i).map(c=>'<td>'+E(c.join(',')||'∅')+'</td>').join('')+'</tr>').reverse().join('')+'</table><h3>CNF grammar</h3><pre>'+E(G.grammarText(r.grammar))+'</pre>';else showDerivation(r.rows||[]);},'primary'));}
